// Usage score - how much fantasy opportunity a player got in one week, as a
// 0-100 percentile that compares across positions. See
// infinileague/docs/usage-score.md for the method; the weights and
// percentile tables (usageCalibration.ts) are generated by
// infinileague/scripts/usage-calibration/calibrate.py.
//
// Each week's carries, targets, and red-zone looks are valued in expected
// fantasy points for the league's scoring, then read as a percentile of
// weekly expected points across every RB/WR/TE (QBs against other QBs).
// Computed per request from the stored weekly stats with the league's own
// scoring - never stored per scoring combo.

import type { ScoringConfig } from "../scoring";
import { FLEX_CALIBRATION, QB_CALIBRATION } from "./usageCalibration";

export type UsagePosition = "QB" | "RB" | "WR" | "TE";

// `total` is the percentile; pass/rush/rec split it by each part's share
// of the week's expected points, so a stacked chart adds up.
export interface UsageScore {
  pass: number;
  rush: number;
  rec: number;
  total: number;
  // Expected fantasy points from the week's opportunities.
  expectedPoints: number;
}

export function isUsagePosition(position: string): position is UsagePosition {
  return position === "QB" || position === "RB" || position === "WR" || position === "TE";
}

// Percentile of `value` against 101 cut points (0th..100th), interpolated
// between the two it falls between.
function percentile(cuts: number[], value: number): number {
  if (value <= (cuts[0] ?? 0)) return 0;
  for (let index = 1; index < cuts.length; index += 1) {
    const upper = cuts[index]!;
    if (value <= upper) {
      const lower = cuts[index - 1]!;
      const share = upper > lower ? (value - lower) / (upper - lower) : 1;
      return index - 1 + share;
    }
  }
  return 100;
}

export function usageScore(
  stats: Record<string, number>,
  position: UsagePosition,
  config: ScoringConfig,
): UsageScore {
  const read = (key: string) => stats[key] ?? 0;
  const flex = FLEX_CALIBRATION[config.scoring][config.teScoring];
  const qb = QB_CALIBRATION[config.scoring][config.sixPointPassTds ? "sixPointPassTds" : "standard"];

  let pass = 0;
  let rush: number;
  let rec: number;
  let cuts: number[];
  if (position === "QB") {
    pass = read("pass_att") * qb.passAtt + read("pass_rz_att") * qb.passRzAtt;
    rush = read("rush_att") * qb.rushAtt + read("rush_rz_att") * qb.rushRzAtt;
    // A QB's rare catch, at the flex rate.
    rec = read("rec_tgt") * flex.recTgt + read("rec_rz_tgt") * flex.recRzTgt;
    cuts = qb.cuts;
  } else {
    rush = read("rush_att") * flex.rushAtt + read("rush_rz_att") * flex.rushRzAtt;
    rec =
      read("rec_tgt") * (flex.recTgt + (position === "TE" ? flex.teTgt : 0)) +
      read("rec_rz_tgt") * flex.recRzTgt;
    cuts = flex.cuts;
  }

  const expectedPoints = pass + rush + rec;
  const total = Math.round(percentile(cuts, expectedPoints));
  const part = (points: number) =>
    expectedPoints > 0 ? Math.round((total * points) / expectedPoints) : 0;
  const parts = { pass: part(pass), rush: part(rush), rec: part(rec) };
  // Rounded parts can miss the total by one - the largest part absorbs it.
  const largest = (Object.keys(parts) as Array<keyof typeof parts>).reduce((a, b) =>
    parts[a] >= parts[b] ? a : b,
  );
  parts[largest] += total - (parts.pass + parts.rush + parts.rec);
  return { ...parts, total, expectedPoints: Math.round(expectedPoints * 10) / 10 };
}
